{
  "name": "通用实验室物理设备",
  "name_en": "Generic Physical Device",
  "manufacturer": "",
  "description": "用于表示可连接到计算机的通用实验室硬件设备，通常可通过 USB 标识进行发现，并支持初始化、命令发送、设备匹配和后台状态监测。该证据未指向具体仪器型号，更像是适用于多类实验设备的通用物理设备抽象。",
  "description_en": "A generic representation of a computer-connected laboratory hardware device, typically discoverable by USB identifiers and supporting initialization, command transfer, device matching, and background status monitoring. The evidence does not indicate a specific instrument model and instead points to a general physical-device abstraction for multiple kinds of lab equipment.",
  "tag_hints": [
    "generic lab instrument",
    "USB device discovery",
    "VID PID matching",
    "background status monitoring",
    "instrument initialization",
    "command-based control"
  ],
  "actions": [
    {
      "action_name": "auto-vidpids",
      "description": "获取设备支持的 USB VID/PID 标识",
      "description_en": "Get the USB VID/PID identifiers supported by the device"
    },
    {
      "action_name": "auto-isCompatibleWith",
      "description": "检查设备是否与给定的序列号和 USB 标识兼容",
      "description_en": "Check whether the device is compatible with a given serial number and USB identifiers"
    },
    {
      "action_name": "auto-commandHelp",
      "description": "列出设备支持的命令说明",
      "description_en": "List help information for commands supported by the device"
    },
    {
      "action_name": "auto-isDebugClass",
      "description": "检查该设备定义是否为调试类",
      "description_en": "Check whether this device definition is a debug class"
    },
    {
      "action_name": "auto-isAbstractClass",
      "description": "检查该设备定义是否为抽象类",
      "description_en": "Check whether this device definition is abstract"
    },
    {
      "action_name": "auto-initializeDevice",
      "description": "初始化设备",
      "description_en": "Initialize the device"
    },
    {
      "action_name": "auto-doInitializeDevice",
      "description": "执行底层设备初始化",
      "description_en": "Perform low-level device initialization"
    },
    {
      "action_name": "auto-initializeIfNeeded",
      "description": "在需要时初始化设备",
      "description_en": "Initialize the device if needed"
    },
    {
      "action_name": "auto-shutdownDevice",
      "description": "关闭设备",
      "description_en": "Shut down the device"
    },
    {
      "action_name": "auto-doShutdownDevice",
      "description": "执行底层设备关闭",
      "description_en": "Perform low-level device shutdown"
    },
    {
      "action_name": "auto-startBackgroundStatusUpdates",
      "description": "启动后台状态更新",
      "description_en": "Start background status updates"
    },
    {
      "action_name": "auto-backgroundStatusUpdates",
      "description": "执行后台状态更新循环",
      "description_en": "Run the background status update cycle"
    },
    {
      "action_name": "auto-doGetStatusUserInfo",
      "description": "获取面向用户的设备状态信息",
      "description_en": "Get user-facing device status information"
    },
    {
      "action_name": "auto-isMonitoring",
      "description": "获取设备是否正在进行后台监测",
      "description_en": "Get whether the device is currently being monitored in the background"
    },
    {
      "action_name": "auto-stopBackgroundStatusUpdates",
      "description": "停止后台状态更新",
      "description_en": "Stop background status updates"
    },
    {
      "action_name": "auto-sendCommand",
      "description": "向设备发送命令",
      "description_en": "Send a command to the device"
    },
    {
      "action_name": "auto-any",
      "description": "获取任意一个可用的兼容设备",
      "description_en": "Get any available compatible device"
    },
    {
      "action_name": "auto-connectedDevices",
      "description": "列出已连接的兼容设备",
      "description_en": "List connected compatible devices"
    },
    {
      "action_name": "auto-uniqueDevice",
      "description": "获取唯一匹配的设备",
      "description_en": "Get the uniquely matching device"
    },
    {
      "action_name": "auto-anyDevice",
      "description": "获取任意一个匹配的设备",
      "description_en": "Get any matching device"
    }
  ]
}

